CREATE TABLE IF NOT EXISTS cms_cache_metrics(id BIGSERIAL PRIMARY KEY,metric_key VARCHAR(190) NOT NULL UNIQUE,hits BIGINT NOT NULL DEFAULT 0,misses BIGINT NOT NULL DEFAULT 0,evictions BIGINT NOT NULL DEFAULT 0,last_hit_at TIMESTAMP,last_miss_at TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_performance_samples(id BIGSERIAL PRIMARY KEY,sample_key VARCHAR(190) NOT NULL,path TEXT NOT NULL,duration_ms INTEGER NOT NULL,memory_peak BIGINT NOT NULL,cache_status VARCHAR(20) NOT NULL DEFAULT 'none',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
